// Jackbox controller over CDP. Usage:
//   node jb.js peek
//   node jb.js click "Some Text Or #selector"
//   node jb.js fill "#selector" "value"
//   node jb.js type "free text"        (types into first visible text input/textarea)
//   node jb.js press Enter
const { chromium } = require('playwright');

async function getPage(browser) {
  const ctx = browser.contexts()[0];
  const page = ctx.pages().find(p => p.url().includes('jackbox')) || ctx.pages()[0];
  return page;
}

(async () => {
  const [cmd, a1, a2] = process.argv.slice(2);
  const browser = await chromium.connectOverCDP('http://localhost:9222');
  const page = await getPage(browser);
  await page.bringToFront();

  if (cmd === 'click') {
    // try as CSS selector first, then as text
    let done = false;
    if (/^[#.\[]/.test(a1)) {
      try { await page.click(a1, { timeout: 4000 }); done = true; } catch {}
    }
    if (!done) { await page.click(`text=${a1}`, { timeout: 6000 }); }
    console.log('clicked:', a1);
  } else if (cmd === 'fill') {
    await page.fill(a1, a2);
    console.log('filled', a1);
  } else if (cmd === 'type') {
    const sel = 'textarea:visible, input[type=text]:visible';
    await page.fill(sel, a1);
    console.log('typed into', sel);
  } else if (cmd === 'press') {
    await page.keyboard.press(a1);
    console.log('pressed', a1);
  }

  // Always end with a peek so we see the resulting state
  await page.waitForTimeout(a1 && cmd !== 'peek' ? 1200 : 300);
  const info = await page.evaluate(() => {
    const vis = el => {
      const r = el.getBoundingClientRect();
      const s = getComputedStyle(el);
      return r.width > 0 && r.height > 0 && s.visibility !== 'hidden' && s.display !== 'none' && s.opacity !== '0';
    };
    const interactive = [...document.querySelectorAll('button, input, textarea, [role=button], a')]
      .filter(vis)
      .map(e => ({
        tag: e.tagName.toLowerCase(),
        type: e.type || '',
        id: e.id || '',
        cls: (typeof e.className === 'string' ? e.className : '').slice(0, 40),
        txt: (e.innerText || e.value || e.placeholder || '').replace(/\s+/g, ' ').trim().slice(0, 50),
        disabled: !!e.disabled,
      }));
    return { text: document.body.innerText.replace(/\n{2,}/g, '\n').trim().slice(0, 1200), interactive };
  });
  console.log('URL:', page.url());
  console.log('TEXT:', JSON.stringify(info.text));
  console.log('INTERACTIVE:', JSON.stringify(info.interactive, null, 1));
  await page.screenshot({ path: '/tmp/jb.png' });
  await browser.close();
})().catch(e => { console.error('ERR', e.message); process.exit(1); });

// Autonomous Jackbox (Quiplash 2) autopilot. Runs locally in a tight loop so it
// never steals window focus and never misses fast voting windows.
// Logs to /tmp/jb-auto.log. Stop by killing the process.
const { chromium } = require('playwright');

const ANSWERS = [
  "A deeply concerning amount of mayonnaise",
  "My therapist's other clients",
  "Aggressive eye contact",
  "The ghost of my gym teacher",
  "Tax fraud, but romantic",
  "A raccoon with a LinkedIn",
  "Whatever's legal in Ohio",
  "My ex and his weird candles",
  "Forbidden soup",
  "The vibes were simply off",
  "A standing ovation for no reason",
  "Three goats in a trench coat",
  "Unsolicited jazz",
  "My browser history, sadly",
  "A haunted Roomba",
];
let answerIdx = 0;
const usedPrompts = new Set();
const votedKeys = new Set();

function log(msg) {
  process.stdout.write(`[${new Date().toISOString()}] ${msg}\n`);
}

(async () => {
  const browser = await chromium.connectOverCDP('http://localhost:9222');
  const ctx = browser.contexts()[0];
  const page = ctx.pages().find(p => p.url().includes('jackbox')) || ctx.pages()[0];
  log('autopilot connected');

  while (true) {
    try {
      const state = await page.evaluate(() => {
        const vis = el => {
          const r = el.getBoundingClientRect();
          const s = getComputedStyle(el);
          return r.width > 0 && r.height > 0 && s.visibility !== 'hidden' && s.display !== 'none' && s.opacity !== '0' && !el.disabled;
        };
        // Voting buttons
        const voteBtns = [...document.querySelectorAll('button')].filter(b =>
          vis(b) && /vote-button/.test(b.className));
        const votes = voteBtns.map(b => (b.innerText || '').trim());
        // Answer input
        const input = document.querySelector('#quiplash-answer-input');
        const submit = document.querySelector('#quiplash-submit-answer');
        const canAnswer = input && submit && vis(input) && vis(submit);
        // Prompt text (best effort): the visible non-button text
        const prompt = (document.body.innerText || '').replace(/\s+/g, ' ').trim().slice(0, 120);
        return { votes, canAnswer, prompt };
      });

      if (state.votes.length >= 2) {
        const key = state.votes.slice().sort().join('||');
        if (!votedKeys.has(key)) {
          // Heuristic: vote the longer (usually more specific / funnier) answer.
          const longer = state.votes[0].length >= state.votes[1].length ? state.votes[0] : state.votes[1];
          try {
            await page.click(`button.quiplash2-vote-button:has-text("${longer.replace(/"/g, '\\"')}")`, { timeout: 1200 });
            votedKeys.add(key);
            log(`VOTED: ${longer}  (over: ${state.votes.filter(v => v !== longer).join(' / ')})`);
          } catch (e) {
            // window may have closed; ignore
          }
        }
      } else if (state.canAnswer) {
        if (!usedPrompts.has(state.prompt)) {
          const ans = ANSWERS[answerIdx % ANSWERS.length];
          answerIdx++;
          try {
            await page.fill('#quiplash-answer-input', ans, { timeout: 1500 });
            await page.click('#quiplash-submit-answer', { timeout: 1500 });
            usedPrompts.add(state.prompt);
            log(`ANSWERED [${state.prompt}] -> "${ans}"`);
          } catch (e) {
            log(`answer attempt failed: ${e.message.split('\n')[0]}`);
          }
        }
      }
    } catch (e) {
      log(`loop error: ${e.message.split('\n')[0]}`);
    }
    await new Promise(r => setTimeout(r, 1200));
  }
})().catch(e => { log('FATAL ' + e.message); process.exit(1); });

// Autonomous Quiplash 2 autopilot, LLM-powered humor.
// - Writing prompts: Claude generates a tailored, punchy joke (<=45 chars).
// - Voting: Claude picks the funnier of the two answers (fast model), with fallback.
// Runs locally; never steals window focus. Logs to stdout (redirected to /tmp/jb-auto.log).
const { chromium } = require('playwright');

const API_KEY = process.env.ANTHROPIC_API_KEY;
const ANSWER_MODEL = 'claude-sonnet-4-6';
const VOTE_MODEL = 'claude-haiku-4-5-20251001';
const NOISE = ['ALEXSCLAUDE', 'SEND', 'SAFETY QUIP', '(HALF POINTS)', 'HALF POINTS', 'ANSWER HERE'];

const usedPrompts = new Map();   // prompt -> answer submitted
const votedKeys = new Map();     // matchup key -> choice

function log(m) { process.stdout.write(`[${new Date().toISOString()}] ${m}\n`); }

async function claude(model, system, user, maxTokens) {
  const res = await fetch('https://api.anthropic.com/v1/messages', {
    method: 'POST',
    headers: {
      'x-api-key': API_KEY,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json',
    },
    body: JSON.stringify({
      model,
      max_tokens: maxTokens,
      system,
      messages: [{ role: 'user', content: user }],
    }),
  });
  if (!res.ok) throw new Error(`API ${res.status}: ${(await res.text()).slice(0,120)}`);
  const data = await res.json();
  return (data.content?.[0]?.text || '').trim();
}

const ANSWER_SYS =
  "You're a player in Quiplash 2, a party game where the funniest answer wins. " +
  "Given a fill-in-the-blank or question prompt, reply with ONE answer only. " +
  "Be punchy, specific, surprising, a little absurd or edgy. Avoid the obvious first joke. " +
  "Hard limit 45 characters. No quotation marks, no preamble, no explanation, no period at the end. " +
  "Just the answer text.";

async function genAnswer(prompt) {
  let a = await claude(ANSWER_MODEL, ANSWER_SYS, `Prompt: ${prompt}`, 60);
  a = a.replace(/^["']|["']$/g, '').replace(/\s+/g, ' ').trim();
  if (a.length > 45) a = a.slice(0, 45).trim();
  return a;
}

async function pickVote(question, a, b) {
  const sys = "You judge Quiplash answers. Reply with exactly one character: A or B — whichever is funnier. Nothing else.";
  const user = `Prompt: ${question || '(unknown)'}\nA: ${a}\nB: ${b}\nFunnier?`;
  const out = (await claude(VOTE_MODEL, sys, user, 5)).toUpperCase();
  if (out.includes('A') && !out.includes('B')) return a;
  if (out.includes('B') && !out.includes('A')) return b;
  return a.length >= b.length ? a : b; // fallback
}

function clean(text) {
  let lines = text.split('\n').map(s => s.trim()).filter(Boolean);
  lines = lines.filter(l => !NOISE.some(n => l.toUpperCase() === n.toUpperCase()));
  // Drop a "WHICH ONE..." voting instruction line if present
  lines = lines.filter(l => !/WHICH ONE DO YOU LIKE/i.test(l));
  return lines.join(' ').slice(0, 160);
}

(async () => {
  if (!API_KEY) { log('FATAL no ANTHROPIC_API_KEY'); process.exit(1); }
  const browser = await chromium.connectOverCDP('http://localhost:9222');
  const ctx = browser.contexts()[0];
  const page = ctx.pages().find(p => p.url().includes('jackbox')) || ctx.pages()[0];
  log('LLM autopilot connected (answers=' + ANSWER_MODEL + ', votes=' + VOTE_MODEL + ')');

  while (true) {
    try {
      const state = await page.evaluate(() => {
        const vis = el => {
          const r = el.getBoundingClientRect();
          const s = getComputedStyle(el);
          return r.width > 0 && r.height > 0 && s.visibility !== 'hidden' && s.display !== 'none' && s.opacity !== '0' && !el.disabled;
        };
        const voteBtns = [...document.querySelectorAll('button')].filter(b => vis(b) && /vote-button/.test(b.className));
        const votes = voteBtns.map(b => (b.innerText || '').trim());
        const input = document.querySelector('#quiplash-answer-input');
        const submit = document.querySelector('#quiplash-submit-answer');
        const canAnswer = !!(input && submit && vis(input) && vis(submit));
        const raw = (document.body.innerText || '');
        return { votes, canAnswer, raw };
      });

      if (state.votes.length >= 2) {
        const [a, b] = state.votes;
        const key = [a, b].slice().sort().join('||');
        if (!votedKeys.has(key)) {
          votedKeys.set(key, true); // claim immediately so we don't double-fire while awaiting API
          let choice;
          try { choice = await pickVote(clean(state.raw), a, b); }
          catch (e) { choice = a.length >= b.length ? a : b; log('vote API fail, fallback: ' + e.message); }
          try {
            await page.click(`button.quiplash2-vote-button:has-text("${choice.replace(/"/g, '\\"')}")`, { timeout: 1500 });
            log(`VOTED: ${choice}  (over: ${[a,b].filter(v => v !== choice).join(' / ')})`);
          } catch { log(`vote window closed before click: ${choice}`); }
        }
      } else if (state.canAnswer) {
        const prompt = clean(state.raw);
        if (prompt && !usedPrompts.has(prompt)) {
          usedPrompts.set(prompt, true); // claim immediately
          let ans;
          try { ans = await genAnswer(prompt); }
          catch (e) { ans = 'A deeply concerning amount of mayonnaise'; log('answer API fail, fallback: ' + e.message); }
          try {
            await page.fill('#quiplash-answer-input', ans, { timeout: 2000 });
            await page.click('#quiplash-submit-answer', { timeout: 2000 });
            usedPrompts.set(prompt, ans);
            log(`ANSWERED [${prompt}] -> "${ans}"`);
          } catch (e) { log(`submit failed for [${prompt}]: ${e.message.split('\n')[0]}`); }
        }
      }
    } catch (e) {
      log('loop error: ' + e.message.split('\n')[0]);
    }
    await new Promise(r => setTimeout(r, 1000));
  }
})().catch(e => { log('FATAL ' + e.message); process.exit(1); });

