// Tee K.O. drawing engine. Opus designs a bold t-shirt graphic as normalized stroke
// paths; we replay them as real mouse strokes with human jitter/timing on the canvas.
const { chromium } = require('playwright');
const API_KEY = process.env.ANTHROPIC_API_KEY;

const DESIGN_SYS =
  "You design BOLD, funny, instantly-readable t-shirt graphics for the game Tee K.O., drawn as simple line art. " +
  "The image is combined with a slogan later, so make ONE clear central subject that reads at a glance. " +
  "Think iconic and a little absurd: a skull in a party hat, a cat DJ with headphones, an angry hotdog, a ghost holding a balloon, a raccoon CEO. " +
  "Output STRICT JSON only, no prose, shaped:\n" +
  '{ "concept": "<=6 words", "strokes": [ { "color": "<one of: black,white,red,orange,yellow,green,blue,purple,pink,brown>", "points": [[x,y],[x,y],...] } ] }\n' +
  "Coordinates are normalized 0..1, origin top-left, y down. Keep everything inside 0.12..0.88 (safe centered area). " +
  "Use 6-16 strokes total. Each stroke is a continuous pen line (>=2 points; curves = many points). Bold simple shapes, no tiny detail. " +
  "Default most linework to black; use 1-3 accent colors max. Do NOT fill large areas (it's slow); suggest fills with outlines/hatching.";

const COLOR_RGB = {
  black:[0,0,0], white:[255,255,255], red:[230,30,30], orange:[240,140,20], yellow:[245,220,30],
  green:[40,180,70], blue:[40,90,220], purple:[140,50,200], pink:[240,110,190], brown:[140,80,40],
};

function rj(text){ const m=text.match(/\{[\s\S]*\}/); return JSON.parse(m?m[0]:text); }

async function design(){
  const r = await fetch('https://api.anthropic.com/v1/messages',{method:'POST',
    headers:{'x-api-key':API_KEY,'anthropic-version':'2023-06-01','content-type':'application/json'},
    body:JSON.stringify({model:'claude-opus-4-8',max_tokens:1500,system:DESIGN_SYS,
      messages:[{role:'user',content:'Design one bold funny t-shirt graphic. JSON only.'}]})});
  const d = await r.json();
  return rj(d.content[0].text);
}

const jitter = (a) => a + (Math.random()-0.5)*a*0;  // placeholder
function nz(px){ return (Math.random()-0.5)*px; }    // small noise in px

async function pickColor(page, name){
  const want = COLOR_RGB[name] || COLOR_RGB.black;
  // Find palette swatches: small buttons/divs with a solid background color.
  const handle = await page.evaluateHandle((want) => {
    const dist=(a,b)=>Math.hypot(a[0]-b[0],a[1]-b[1],a[2]-b[2]);
    const parse=(s)=>{const m=s&&s.match(/rgba?\(([^)]+)\)/);if(!m)return null;const p=m[1].split(',').map(Number);return [p[0],p[1],p[2]];};
    const els=[...document.querySelectorAll('button,div,li,span')];
    let best=null,bd=1e9;
    for(const el of els){const r=el.getBoundingClientRect();if(r.width<14||r.width>70||r.height<14||r.height>70)continue;
      const bg=parse(getComputedStyle(el).backgroundColor);if(!bg)continue;
      const d=dist(bg,want);if(d<bd){bd=d;best=el;}}
    return bd<60?best:null;
  }, want);
  const el = handle.asElement();
  if(el){ try{ await el.click({timeout:800}); }catch{} }
}

async function drawStroke(page, ox, oy, w, h, points){
  const map = (p)=>[ ox + p[0]*w + nz(1.5), oy + p[1]*h + nz(1.5) ];
  let [x,y]=map(points[0]);
  await page.mouse.move(x,y);
  await page.mouse.down();
  for(let i=1;i<points.length;i++){
    const [tx,ty]=map(points[i]);
    // interpolate the segment into small jittered steps for a hand-drawn wobble
    const segs = Math.max(2, Math.round(Math.hypot(tx-x,ty-y)/8));
    for(let s=1;s<=segs;s++){
      const fx = x+(tx-x)*s/segs + nz(1.2);
      const fy = y+(ty-y)*s/segs + nz(1.2);
      await page.mouse.move(fx,fy);
    }
    x=tx; y=ty;
  }
  await page.mouse.up();
}

(async () => {
  const browser = await chromium.connectOverCDP('http://localhost:9222');
  const ctx = browser.contexts()[0];
  const page = ctx.pages().find(p=>p.url().includes('jackbox'))||ctx.pages()[0];

  let drawn = 0;
  while (drawn < 3) {
    // Wait (briefly) for a drawable canvas + submit button
    const rect = await page.evaluate(() => {
      const c=[...document.querySelectorAll('canvas')].find(c=>{const r=c.getBoundingClientRect();return r.width>200&&r.height>200;});
      const submit=document.querySelector('#awshirt-submitdrawing');
      if(!c||!submit) return null;
      const r=c.getBoundingClientRect();
      return {x:r.x,y:r.y,w:r.width,h:r.height};
    });
    if(!rect){ console.log('no draw canvas; stopping after', drawn); break; }

    const plan = await design();
    console.log(`DESIGN #${drawn+1}:`, plan.concept, '-', plan.strokes.length, 'strokes');
    const pad = 0; // strokes already constrained to 0.12..0.88
    let lastColor=null;
    for(const st of plan.strokes){
      if(st.color && st.color!==lastColor){ await pickColor(page, st.color); lastColor=st.color; }
      const pts=(st.points||[]).filter(p=>Array.isArray(p)&&p.length===2);
      if(pts.length>=2) await drawStroke(page, rect.x, rect.y, rect.w, rect.h, pts);
      await page.waitForTimeout(40);
    }
    // submit
    try{ await page.click('#awshirt-submitdrawing',{timeout:2000}); console.log('submitted drawing', drawn+1); }
    catch(e){ console.log('submit failed:', e.message.split('\n')[0]); }
    drawn++;
    await page.waitForTimeout(2500); // wait for next canvas to appear (if any)
  }
  console.log('done, drawings:', drawn);
  await browser.close();
})().catch(e=>{console.error('ERR',e.message);process.exit(1);});

// Tee K.O. slogan phase: generate many funny shirt slogans and submit them
