// Join a Jackbox room.  Usage: node join.js <ROOMCODE> [name]
// Navigates the existing CDP Chrome to jackbox.tv, dismisses the cookie banner,
// enters the room code + player name, and clicks PLAY.
const { chromium } = require('playwright');
(async () => {
  const code = (process.argv[2] || '').toUpperCase();
  const name = process.argv[3] || 'AlexsClaude';   // <=12 chars; signals it's Alex's bot
  if (!code) { console.error('usage: node join.js <ROOMCODE> [name]'); process.exit(1); }
  const browser = await chromium.connectOverCDP('http://localhost:9222');
  const ctx = browser.contexts()[0];
  const page = ctx.pages().find(p => p.url().includes('jackbox')) || ctx.pages()[0];
  await page.goto('https://jackbox.tv/', { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(1500);
  try { await page.click('text=Reject All', { timeout: 2500 }); } catch {}
  await page.waitForTimeout(400);
  await page.fill('#roomcode', code);
  await page.fill('#username', name.slice(0, 12));
  await page.click('#button-join');
  await page.waitForTimeout(2500);
  const txt = (await page.evaluate(() => document.body.innerText)).replace(/\s+/g, ' ').trim().slice(0, 160);
  console.log('joined', code, 'as', name, '->', txt);
  await browser.close();
})().catch(e => { console.error('ERR', e.message); process.exit(1); });

// Reliable screenshot via raw CDP. Use this instead of page.screenshot() — Playwright's
// screenshot waits for fonts to load and HANGS on jackbox.tv. CDP captureScreenshot doesn't.
// Usage: node shot.js [outfile]   (default /tmp/jb.png).  Read the PNG with vision.
const { chromium } = require('playwright');
const fs = require('fs');
(async () => {
  const out = process.argv[2] || '/tmp/jb.png';
  const browser = await chromium.connectOverCDP('http://localhost:9222');
  const ctx = browser.contexts()[0];
  const page = ctx.pages().find(p => p.url().includes('jackbox')) || ctx.pages()[0];
  const session = await ctx.newCDPSession(page);
  const { data } = await session.send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync(out, Buffer.from(data, 'base64'));
  console.log('saved', out);
  await browser.close();
})().catch(e => { console.error('ERR', e.message); process.exit(1); });

// Generic Jackbox controller over CDP. Drives jackbox.tv WITHOUT stealing window focus.
// Use for one-off / manual interaction and for discovering a new game's DOM (peek).
// Usage:
//   node control.js peek                      -> dump page text + visible interactive elements
//   node control.js click "Text or #selector"
//   node control.js fill "#selector" "value"
//   node control.js type "free text"          -> first visible text input/textarea
//   node control.js press Enter
const { chromium } = require('playwright');

(async () => {
  const [cmd, a1, a2] = process.argv.slice(2);
  const browser = await chromium.connectOverCDP('http://localhost:9222');
  const ctx = browser.contexts()[0];
  const page = ctx.pages().find(p => p.url().includes('jackbox')) || ctx.pages()[0];
  // Intentionally do NOT bringToFront — play quietly without stealing the user's focus.

  if (cmd === 'click') {
    let done = false;
    if (/^[#.\[]/.test(a1)) { try { await page.click(a1, { timeout: 4000 }); done = true; } catch {} }
    if (!done) await page.click(`text=${a1}`, { timeout: 6000 });
    console.log('clicked:', a1);
  } else if (cmd === 'fill') {
    await page.fill(a1, a2); console.log('filled', a1);
  } else if (cmd === 'type') {
    await page.fill('textarea:visible, input[type=text]:visible', a1); console.log('typed');
  } else if (cmd === 'press') {
    await page.keyboard.press(a1); console.log('pressed', a1);
  }

  await page.waitForTimeout(a1 && cmd !== 'peek' ? 1200 : 300);
  const info = await page.evaluate(() => {
    const vis = el => {
      const r = el.getBoundingClientRect(); const s = getComputedStyle(el);
      return r.width > 0 && r.height > 0 && s.visibility !== 'hidden' && s.display !== 'none' && s.opacity !== '0';
    };
    const interactive = [...document.querySelectorAll('button, input, textarea, [role=button], a, canvas')]
      .filter(vis).map(e => ({
        tag: e.tagName.toLowerCase(), type: e.type || '', id: e.id || '',
        cls: (typeof e.className === 'string' ? e.className : '').slice(0, 40),
        txt: (e.innerText || e.value || e.placeholder || '').replace(/\s+/g, ' ').trim().slice(0, 50),
        disabled: !!e.disabled,
      }));
    return { text: document.body.innerText.replace(/\n{2,}/g, '\n').trim().slice(0, 1200), interactive };
  });
  console.log('URL:', page.url());
  console.log('TEXT:', JSON.stringify(info.text));
  console.log('INTERACTIVE:', JSON.stringify(info.interactive, null, 1));
  // best-effort screenshot (use shot.js for a guaranteed one)
  try { await page.screenshot({ path: '/tmp/jb.png', timeout: 4000 }); } catch {}
  await browser.close();
})().catch(e => { console.error('ERR', e.message); process.exit(1); });

// Autonomous Quiplash 2 autopilot, LLM-powered humor. Runs locally in a tight loop so it
// never steals window focus and never misses fast voting windows.
//  - Writing prompts: Opus brainstorms 5 candidates, ships the funniest (<=45 chars).
//  - Voting: Sonnet picks the funnier of the two answers.
// NEVER uses the half-points "Safety Quip" — always submits a real full-points answer.
// Needs ANTHROPIC_API_KEY in env. Logs to stdout. Stop by killing the process.
const { chromium } = require('playwright');

const API_KEY = process.env.ANTHROPIC_API_KEY;
const ANSWER_MODEL = 'claude-opus-4-8';
const VOTE_MODEL = 'claude-sonnet-4-6';
const NOISE = ['ALEXSCLAUDE', 'SEND', 'SAFETY QUIP', '(HALF POINTS)', 'HALF POINTS', 'ANSWER HERE'];

const usedPrompts = new Map();
const votedKeys = new Map();
function log(m) { process.stdout.write(`[${new Date().toISOString()}] ${m}\n`); }

async function claude(model, system, user, maxTokens) {
  const res = await fetch('https://api.anthropic.com/v1/messages', {
    method: 'POST',
    headers: { 'x-api-key': API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
    body: JSON.stringify({ model, max_tokens: maxTokens, system, messages: [{ role: 'user', content: user }] }),
  });
  if (!res.ok) throw new Error(`API ${res.status}: ${(await res.text()).slice(0, 120)}`);
  const data = await res.json();
  return (data.content?.[0]?.text || '').trim();
}

// Comedic principles distilled from researching what wins Quiplash:
const ANSWER_SYS =
  "You are a ringer at Quiplash 2 — the player whose answers the whole room reads aloud and loses it over. " +
  "The crowd votes head-to-head, so your answer must beat the other player's. Funny wins, not clever-for-clever's-sake.\n\n" +
  "WHAT WINS (use these, don't just list them):\n" +
  "- SPECIFICITY beats generic. A vivid concrete image wins: 'Pulling a Beyoncé' > 'dancing'. Use real brand names, oddly specific numbers, named places.\n" +
  "- COMMIT TO THE ABSURD. No subtlety, no hedging. 'Cream of Existential Dread' > 'a bad flavor'.\n" +
  "- SMART-STUPID JUXTAPOSITION. Pair the highbrow with the idiotic: 'A TED Talk on the socioeconomic impact of carrots'.\n" +
  "- MISDIRECTION. The first joke everyone thinks of is dead on arrival. Skip it. Your 3rd or 4th idea is the funny one.\n" +
  "- RELATABLE DARKNESS. Shared misery lands: regret, debt, your ex, the DMV, crushing existential dread, HR.\n" +
  "- PUNCHY & FRONT-LOADED-LAST. Short. Put the funniest WORD at the very end so it lands when read aloud.\n" +
  "- A confident weird specific noun phrase usually beats a sentence.\n\n" +
  "AVOID: clichés, puns unless genuinely great, anything safe or milquetoast, explaining the joke, hashtags, emoji.\n\n" +
  "THE BAR (aim HERE, do not copy it): 'A cupholder shaped like the middle class.' " +
  "Why it's elite: a mundane object becomes a socioeconomic gut-punch — the cupholder is shrinking to nothing, like the middle class. " +
  "Surreal physical image + a topical/political truth + the devastating idea landing on the final word. " +
  "Reach for that: take an ordinary noun and weaponize it as a metaphor for something we're all quietly grim about (the economy, healthcare, aging, dating apps, work). Don't settle for merely 'quirky'.\n\n" +
  "PROCESS: Silently brainstorm 5 candidates using DIFFERENT techniques above. Then pick the single funniest one to read aloud to a room. " +
  "Output ONLY that one, on a final line prefixed exactly with 'FINAL:'. Hard limit 45 characters for the final answer. " +
  "No quotation marks, no trailing period.";

function extractFinal(text) {
  const m = text.match(/FINAL:\s*(.+)\s*$/im);
  let a = (m ? m[1] : text.split('\n').filter(Boolean).pop() || '').trim();
  a = a.replace(/^["'`]|["'`.]+$/g, '').replace(/\s+/g, ' ').trim();
  if (a.length > 45) {
    // Trim to a clean word boundary, never mid-word, to avoid broken-looking cuts.
    let cut = a.slice(0, 45);
    const sp = cut.lastIndexOf(' ');
    if (sp > 20) cut = cut.slice(0, sp);
    a = cut.replace(/[\s,;:.-]+$/, '').trim();
  }
  return a;
}

async function genAnswer(prompt) {
  const raw = await claude(ANSWER_MODEL, ANSWER_SYS,
    `Prompt to answer: ${prompt}\n\nBrainstorm 5, then give your funniest as FINAL:`, 400);
  return extractFinal(raw);
}

async function pickVote(question, a, b) {
  const sys = "You judge Quiplash answers. Reply with exactly one character: A or B — whichever is funnier. Nothing else.";
  const user = `Prompt: ${question || '(unknown)'}\nA: ${a}\nB: ${b}\nFunnier?`;
  const out = (await claude(VOTE_MODEL, sys, user, 5)).toUpperCase();
  if (out.includes('A') && !out.includes('B')) return a;
  if (out.includes('B') && !out.includes('A')) return b;
  return a.length >= b.length ? a : b;
}

function clean(text) {
  let lines = text.split('\n').map(s => s.trim()).filter(Boolean);
  lines = lines.filter(l => !NOISE.some(n => l.toUpperCase() === n.toUpperCase()));
  lines = lines.filter(l => !/WHICH ONE DO YOU LIKE/i.test(l));
  return lines.join(' ').slice(0, 160);
}

(async () => {
  if (!API_KEY) { log('FATAL no ANTHROPIC_API_KEY'); process.exit(1); }
  const browser = await chromium.connectOverCDP('http://localhost:9222');
  const ctx = browser.contexts()[0];
  const page = ctx.pages().find(p => p.url().includes('jackbox')) || ctx.pages()[0];
  log('Quiplash autopilot connected (answers=' + ANSWER_MODEL + ', votes=' + VOTE_MODEL + ')');

  while (true) {
    try {
      const state = await page.evaluate(() => {
        const vis = el => {
          const r = el.getBoundingClientRect(); const s = getComputedStyle(el);
          return r.width > 0 && r.height > 0 && s.visibility !== 'hidden' && s.display !== 'none' && s.opacity !== '0' && !el.disabled;
        };
        const voteBtns = [...document.querySelectorAll('button')].filter(b => vis(b) && /vote-button/.test(b.className));
        const votes = voteBtns.map(b => (b.innerText || '').trim());
        const input = document.querySelector('#quiplash-answer-input');
        const submit = document.querySelector('#quiplash-submit-answer');
        const canAnswer = !!(input && submit && vis(input) && vis(submit));
        const raw = (document.body.innerText || '');
        return { votes, canAnswer, raw };
      });

      if (state.votes.length >= 2) {
        const [a, b] = state.votes;
        const key = [a, b].slice().sort().join('||');
        if (!votedKeys.has(key)) {
          votedKeys.set(key, true); // claim immediately so we don't double-fire while awaiting API
          let choice;
          try { choice = await pickVote(clean(state.raw), a, b); }
          catch (e) { choice = a.length >= b.length ? a : b; log('vote API fail, fallback: ' + e.message); }
          try {
            await page.click(`button.quiplash2-vote-button:has-text("${choice.replace(/"/g, '\\"')}")`, { timeout: 1500 });
            log(`VOTED: ${choice}  (over: ${[a, b].filter(v => v !== choice).join(' / ')})`);
          } catch { log(`vote window closed before click: ${choice}`); }
        }
      } else if (state.canAnswer) {
        const prompt = clean(state.raw);
        if (prompt && !usedPrompts.has(prompt)) {
          usedPrompts.set(prompt, true); // claim immediately
          let ans;
          try { ans = await genAnswer(prompt); }
          catch (e) { ans = 'A deeply concerning amount of mayonnaise'; log('answer API fail, fallback: ' + e.message); }
          try {
            await page.fill('#quiplash-answer-input', ans, { timeout: 2000 });
            await page.click('#quiplash-submit-answer', { timeout: 2000 }); // never #quiplash-submit-safetyquip
            usedPrompts.set(prompt, ans);
            log(`ANSWERED [${prompt}] -> "${ans}"`);
          } catch (e) { log(`submit failed for [${prompt}]: ${e.message.split('\n')[0]}`); }
        }
      }
    } catch (e) {
      log('loop error: ' + e.message.split('\n')[0]);
    }
    await new Promise(r => setTimeout(r, 1000));
  }
})().catch(e => { log('FATAL ' + e.message); process.exit(1); });

// Unified Tee K.O. autopilot. Detects the live phase each tick and acts instantly:
//  - DRAW  : Opus designs a bold graphic -> replayed as human-jittered mouse strokes -> submit
//  - SLOGAN: pre-generated funny-slogan queue -> submit continuously
//  - VOTE  : text-first (instant Haiku judgment); CDP-screenshot + Sonnet vision for image-only shirts
// Runs locally in a tight loop; never steals window focus. Heartbeat every 8s.
// Needs ANTHROPIC_API_KEY in env. Logs to stdout. Stop by killing the process.
const { chromium } = require('playwright');
const API_KEY = process.env.ANTHROPIC_API_KEY;
const log = m => process.stdout.write(`[${new Date().toISOString()}] ${m}\n`);

const COLOR_RGB = { black:[0,0,0], white:[255,255,255], red:[230,30,30], orange:[240,140,20],
  yellow:[245,220,30], green:[40,180,70], blue:[40,90,220], purple:[140,50,200], pink:[240,110,190], brown:[140,80,40] };
const nz = px => (Math.random()-0.5)*px;
const rjObj = t => { const m=t.match(/\{[\s\S]*\}/); return JSON.parse(m?m[0]:t); };
const rjArr = t => { const m=t.match(/\[[\s\S]*\]/); return JSON.parse(m?m[0]:t); };

async function claude(model, system, content, maxTokens){
  const r = await fetch('https://api.anthropic.com/v1/messages',{method:'POST',
    headers:{'x-api-key':API_KEY,'anthropic-version':'2023-06-01','content-type':'application/json'},
    body:JSON.stringify({model,max_tokens:maxTokens,system,messages:[{role:'user',content}]})});
  if(!r.ok) throw new Error(`API ${r.status}: ${(await r.text()).slice(0,120)}`);
  const d = await r.json(); return d.content[0].text;
}

// ---- content generators ----
const DESIGN_SYS =
  "You design BOLD, funny, instantly-readable t-shirt graphics for Tee K.O., as simple line art with ONE clear central subject. "+
  "Iconic + absurd (skull in party hat, cat DJ with headphones, angry coffee cup, raccoon CEO, ghost with balloon, T-Rex flexing tiny arms). "+
  'Output STRICT JSON: { "concept":"<=6 words", "strokes":[ {"color":"black|white|red|orange|yellow|green|blue|purple|pink|brown","points":[[x,y],...]} ] }. '+
  "Normalized 0..1, origin top-left, y down, keep inside 0.12..0.88, centered. 6-16 strokes, each a continuous pen line (>=2 pts; curves=many pts). "+
  "Bold simple shapes, no tiny detail, mostly black with 1-3 accents, no big fills.";
async function design(){ return rjObj(await claude('claude-opus-4-8', DESIGN_SYS, 'Design one bold funny t-shirt graphic. JSON only.', 1500)); }

// Same comedic principles as quiplash.js — specificity, absurd, smart-stupid, relatable darkness, punchy.
const SLOGAN_SYS =
  "You write SLOGANS for t-shirts in Tee K.O.; funniest shirt wins the room's vote. Principles: specificity > generic; commit to the absurd; "+
  "smart-stupid juxtaposition; relatable darkness (debt, your ex, the DMV, burnout, existential dread, HR); punchy with the funniest word last. "+
  "The bar (aim here, don't copy): 'A cupholder shaped like the middle class' — a mundane thing weaponized into a socioeconomic gut-punch. "+
  "Feel like real absurd merch; mix fake-motivational, cursed-corporate, doomer, weird-flex. "+
  "No clichés, hashtags, emoji, or quotes. Each <=45 chars. Output STRICT JSON: array of strings only.";
async function genSlogans(n){ return rjArr(await claude('claude-opus-4-8', SLOGAN_SYS,
  `Write ${n} distinct genuinely funny t-shirt slogans. JSON array only.`, 1200))
  .map(s=>String(s).replace(/^["'`]|["'`]$/g,'').trim()).filter(Boolean).map(s=>s.slice(0,45)); }

// ---- drawing primitives ----
async function pickColor(page, name){
  const want = COLOR_RGB[name]||COLOR_RGB.black;
  const handle = await page.evaluateHandle((want)=>{
    const dist=(a,b)=>Math.hypot(a[0]-b[0],a[1]-b[1],a[2]-b[2]);
    const parse=s=>{const m=s&&s.match(/rgba?\(([^)]+)\)/);if(!m)return null;const p=m[1].split(',').map(Number);return[p[0],p[1],p[2]];};
    let best=null,bd=1e9;
    for(const el of document.querySelectorAll('button,div,li,span')){const r=el.getBoundingClientRect();
      if(r.width<14||r.width>70||r.height<14||r.height>70)continue;
      const bg=parse(getComputedStyle(el).backgroundColor);if(!bg)continue;
      const d=dist(bg,want);if(d<bd){bd=d;best=el;}}
    return bd<60?best:null;
  }, want);
  const el=handle.asElement(); if(el){ try{ await el.click({timeout:700}); }catch{} }
}
async function drawStroke(page, ox, oy, w, h, points){
  const map=p=>[ox+p[0]*w+nz(1.5), oy+p[1]*h+nz(1.5)];
  let [x,y]=map(points[0]); await page.mouse.move(x,y); await page.mouse.down();
  for(let i=1;i<points.length;i++){ const [tx,ty]=map(points[i]);
    // interpolate each segment into small jittered steps for a hand-drawn wobble
    const segs=Math.max(2,Math.round(Math.hypot(tx-x,ty-y)/8));
    for(let s=1;s<=segs;s++){ await page.mouse.move(x+(tx-x)*s/segs+nz(1.2), y+(ty-y)*s/segs+nz(1.2)); }
    x=tx; y=ty; }
  await page.mouse.up();
}
async function doDrawing(page, rect){
  const plan = await design();
  log(`DRAW: ${plan.concept} (${plan.strokes.length} strokes)`);
  let last=null;
  for(const st of plan.strokes){
    if(st.color&&st.color!==last){ await pickColor(page, st.color); last=st.color; }
    const pts=(st.points||[]).filter(p=>Array.isArray(p)&&p.length===2);
    if(pts.length>=2) await drawStroke(page, rect.x, rect.y, rect.w, rect.h, pts);
    await page.waitForTimeout(30);
  }
}

// ---- vision vote (fallback for image-only shirts) ----
async function visionVote(page, cdp, votes){
  const { data } = await cdp.send('Page.captureScreenshot', { format:'png' });
  const orient = (Math.abs(votes[0].cx-votes[1].cx) >= Math.abs(votes[0].cy-votes[1].cy)) ? 'LR' : 'TB';
  const labelA = orient==='LR'?'LEFT':'TOP', labelB = orient==='LR'?'RIGHT':'BOTTOM';
  const sorted = orient==='LR' ? [...votes].sort((a,b)=>a.cx-b.cx) : [...votes].sort((a,b)=>a.cy-b.cy);
  const out = (await claude('claude-sonnet-4-6',
    'You judge a Tee K.O. shirt battle. Reply with exactly one word: '+labelA+' or '+labelB+' — whichever t-shirt is funnier/better.',
    [{type:'image',source:{type:'base64',media_type:'image/png',data}},
     {type:'text',text:`Two shirts are shown. Which is funnier: ${labelA} or ${labelB}? One word.`}], 5)).toUpperCase();
  const pick = out.includes(labelB) ? sorted[1] : sorted[0];
  await page.mouse.click(pick.cx, pick.cy);
  log(`VOTE(vision): ${out.trim()} -> ${Math.round(pick.cx)},${Math.round(pick.cy)}`);
}

// ---- DOM phase probe ----
async function probe(page){
  return await page.evaluate(()=>{
    const vis=el=>{const r=el.getBoundingClientRect();const s=getComputedStyle(el);
      return r.width>0&&r.height>0&&s.visibility!=='hidden'&&s.display!=='none'&&!el.disabled;};
    const canvasEl=[...document.querySelectorAll('canvas')].find(c=>{const r=c.getBoundingClientRect();return r.width>200&&r.height>200;});
    let canvas=null, blank=null;
    if(canvasEl){ const r=canvasEl.getBoundingClientRect(); canvas={x:r.x,y:r.y,w:r.width,h:r.height};
      try{ const cx=canvasEl.getContext('2d'); if(cx){ const s=80;
        const id=cx.getImageData(0,0,Math.min(canvasEl.width,400),Math.min(canvasEl.height,400)).data;
        let dark=0,n=0; for(let i=0;i<id.length;i+=4*s){ n++; if(id[i]<240||id[i+1]<240||id[i+2]<240) dark++; }
        blank=(dark/n)<0.01; } }catch(e){ blank=null; }
    }
    const submitDraw=document.querySelector('#awshirt-submitdrawing');
    const textInput=[...document.querySelectorAll('input[type=text],textarea')].filter(vis).find(i=>i.id!=='roomcode'&&i.id!=='username');
    const submitBtn=[...document.querySelectorAll('button')].filter(vis).find(b=>/submit|send|done/i.test(b.id)||/^(SEND|SUBMIT|DONE|OK)$/i.test((b.innerText||'').trim()));
    const voteEls=[...document.querySelectorAll('button,[role=button],img,div')].filter(el=>vis(el)&&/vote/i.test((el.id+' '+el.className).toString()))
      .map(el=>{const r=el.getBoundingClientRect();return{cx:r.x+r.width/2,cy:r.y+r.height/2,a:r.width*r.height,txt:(el.innerText||'').trim().slice(0,60)};})
      .filter(v=>v.a>5000);
    return {
      canvas, blank,
      hasSubmitDraw: !!(submitDraw && vis(submitDraw)),
      textInputSel: textInput?(textInput.id?('#'+textInput.id):'textarea'):null,
      submitBtnId: submitBtn?submitBtn.id:null,
      votes: voteEls.slice(0,2),
      text: document.body.innerText.replace(/\s+/g,' ').trim().slice(0,80),
    };
  });
}

(async ()=>{
  if(!API_KEY){ log('FATAL no ANTHROPIC_API_KEY'); process.exit(1); }
  const browser = await chromium.connectOverCDP('http://localhost:9222');
  const ctx = browser.contexts()[0];
  const page = ctx.pages().find(p=>p.url().includes('jackbox'))||ctx.pages()[0];
  const cdp = await ctx.newCDPSession(page);
  log('Tee K.O. autopilot connected');

  let queue = [];
  (async()=>{ try{ queue = await genSlogans(30); log('slogan queue: '+queue.length); }catch(e){ log('slogan gen fail '+e.message); } })();

  let drewThisCanvas=false, lastSlogan=0, votedSig='', lastHB=0;
  while(true){
    try{
      const st = await probe(page);

      // heartbeat so we can see it's alive and what phase it sees
      if(Date.now()-lastHB>8000){ lastHB=Date.now();
        const phase = st.votes.length>=2?'VOTE':(st.canvas&&st.hasSubmitDraw?'DRAW':(st.textInputSel&&st.submitBtnId?'SLOGAN':'idle'));
        log(`hb phase=${phase} votes=${st.votes.length} canvas=${!!st.canvas} text="${st.text.slice(0,40)}"`); }

      // VOTE: text-first (instant via Haiku), vision fallback for image-only shirts
      if(st.votes.length>=2){
        const [a,b]=st.votes;
        const sig = (a.txt||a.cx+','+a.cy)+'||'+(b.txt||b.cx+','+b.cy);
        if(sig!==votedSig){ votedSig=sig;
          try{
            if(a.txt && b.txt && a.txt.length>1 && b.txt.length>1){
              const out=(await claude('claude-haiku-4-5-20251001',
                'You judge a Tee K.O. shirt battle by slogan. Reply with exactly one letter: A or B — the funnier one.',
                `A: ${a.txt}\nB: ${b.txt}`, 5)).toUpperCase();
              const pick = (out.includes('B')&&!out.includes('A')) ? b : a;
              await page.mouse.click(pick.cx, pick.cy);
              log(`VOTE(text): "${pick.txt}"  (over "${(pick===a?b:a).txt}")`);
            } else {
              await visionVote(page, cdp, st.votes);
            }
          }catch(e){ log('vote fail '+e.message.split('\n')[0]); }
        }
      }
      // DRAW
      else if(st.canvas && st.hasSubmitDraw){
        if(st.blank===true) drewThisCanvas=false;       // fresh blank canvas -> ready to draw again
        if(!drewThisCanvas){
          drewThisCanvas=true;
          try{ await doDrawing(page, st.canvas); await page.click('#awshirt-submitdrawing',{timeout:2500}); log('submitted drawing'); }
          catch(e){ log('draw/submit fail '+e.message.split('\n')[0]); }
        }
      }
      // SLOGAN
      else if(st.textInputSel && st.submitBtnId){
        if(queue.length===0){ try{ queue = await genSlogans(20); log('refilled slogans '+queue.length); }catch{} }
        if(queue.length && Date.now()-lastSlogan>700){
          const s=queue.shift(); lastSlogan=Date.now();
          try{ await page.fill(st.textInputSel,s,{timeout:1500}); await page.click('#'+st.submitBtnId,{timeout:1500}); log('SLOGAN: '+s); }
          catch(e){ log('slogan submit fail '+e.message.split('\n')[0]); }
        }
      }

      if(!st.canvas) drewThisCanvas=false;
    }catch(e){ log('loop err '+e.message.split('\n')[0]); }
    await new Promise(r=>setTimeout(r, 600));
  }
})().catch(e=>{ log('FATAL '+e.message); process.exit(1); });
